// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Health check
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Log in with email and password
	// (POST /v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// End the current session
	// (POST /v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// End every session of the current user, on all devices
	// (POST /v1/auth/logout-all)
	LogoutAll(w http.ResponseWriter, r *http.Request)
	// Current user and their projects
	// (GET /v1/auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// Set a new password with a reset token
	// (POST /v1/auth/password-reset/confirm)
	ConfirmPasswordReset(w http.ResponseWriter, r *http.Request)
	// Email a password reset link
	// (POST /v1/auth/password-reset/request)
	RequestPasswordReset(w http.ResponseWriter, r *http.Request)
	// Create an account
	// (POST /v1/auth/signup)
	Signup(w http.ResponseWriter, r *http.Request)
	// Confirm the email address with the token from the verification email
	// (POST /v1/auth/verify-email)
	VerifyEmail(w http.ResponseWriter, r *http.Request)
	// Send the verification email again
	// (POST /v1/auth/verify-email/resend)
	ResendVerification(w http.ResponseWriter, r *http.Request)
	// Explore product events
	// (GET /v1/events)
	ListEvents(w http.ResponseWriter, r *http.Request, params ListEventsParams)
	// Event names with counts
	// (GET /v1/events/names)
	ListEventNames(w http.ResponseWriter, r *http.Request, params ListEventNamesParams)
	// Run a funnel
	// (POST /v1/funnels/query)
	QueryFunnel(w http.ResponseWriter, r *http.Request, params QueryFunnelParams)
	// Accept an invite as the logged-in user
	// (POST /v1/invites/accept)
	AcceptInvite(w http.ResponseWriter, r *http.Request)
	// Describe an invite from its token
	// (POST /v1/invites/lookup)
	LookupInvite(w http.ResponseWriter, r *http.Request)
	// List issues
	// (GET /v1/issues)
	ListIssues(w http.ResponseWriter, r *http.Request, params ListIssuesParams)
	// Get an issue with its most recent events
	// (GET /v1/issues/{id})
	GetIssue(w http.ResponseWriter, r *http.Request, id IssueID, params GetIssueParams)
	// Change an issue's status
	// (PATCH /v1/issues/{id})
	UpdateIssue(w http.ResponseWriter, r *http.Request, id IssueID)
	// Metrics received in the time range
	// (GET /v1/metrics/names)
	ListMetricNames(w http.ResponseWriter, r *http.Request, params ListMetricNamesParams)
	// Query one metric as time series
	// (GET /v1/metrics/query)
	QueryMetric(w http.ResponseWriter, r *http.Request, params QueryMetricParams)
	// Security audit log of the organization
	// (GET /v1/orgs/{org_id}/audit-log)
	ListAuditLog(w http.ResponseWriter, r *http.Request, orgId OrgPath, params ListAuditLogParams)
	// Pending invites
	// (GET /v1/orgs/{org_id}/invites)
	ListInvites(w http.ResponseWriter, r *http.Request, orgId OrgPath)
	// Invite someone by email
	// (POST /v1/orgs/{org_id}/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request, orgId OrgPath)
	// Revoke a pending invite
	// (POST /v1/orgs/{org_id}/invites/{invite_id}/revoke)
	RevokeInvite(w http.ResponseWriter, r *http.Request, orgId OrgPath, inviteId int64)
	// Members of the organization
	// (GET /v1/orgs/{org_id}/members)
	ListMembers(w http.ResponseWriter, r *http.Request, orgId OrgPath)
	// Remove a member from the organization
	// (POST /v1/orgs/{org_id}/members/{user_id}/remove)
	RemoveMember(w http.ResponseWriter, r *http.Request, orgId OrgPath, userId int64)
	// Change a member's role
	// (POST /v1/orgs/{org_id}/members/{user_id}/role)
	SetMemberRole(w http.ResponseWriter, r *http.Request, orgId OrgPath, userId int64)
	// Projects the user is a member of
	// (GET /v1/projects)
	ListProjects(w http.ResponseWriter, r *http.Request)
	// Create a project in the user's organization
	// (POST /v1/projects)
	CreateProject(w http.ResponseWriter, r *http.Request)
	// Rename a project
	// (PATCH /v1/projects/{project_id})
	UpdateProject(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// List notification channels
	// (GET /v1/projects/{project_id}/alert-channels)
	ListAlertChannels(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Add a notification channel
	// (POST /v1/projects/{project_id}/alert-channels)
	CreateAlertChannel(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Delete a channel and remove it from rules
	// (DELETE /v1/projects/{project_id}/alert-channels/{channel_id})
	DeleteAlertChannel(w http.ResponseWriter, r *http.Request, projectId ProjectPath, channelId ChannelPath)
	// Send a test notification
	// (POST /v1/projects/{project_id}/alert-channels/{channel_id}/test)
	TestAlertChannel(w http.ResponseWriter, r *http.Request, projectId ProjectPath, channelId ChannelPath)
	// List alert rules with their current state
	// (GET /v1/projects/{project_id}/alerts)
	ListAlerts(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Create an alert rule
	// (POST /v1/projects/{project_id}/alerts)
	CreateAlert(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Chart a rule's metric against its threshold
	// (POST /v1/projects/{project_id}/alerts/preview)
	PreviewAlert(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Delete a rule and its history
	// (DELETE /v1/projects/{project_id}/alerts/{alert_id})
	DeleteAlert(w http.ResponseWriter, r *http.Request, projectId ProjectPath, alertId AlertPath)
	// Get a rule with its recent history
	// (GET /v1/projects/{project_id}/alerts/{alert_id})
	GetAlert(w http.ResponseWriter, r *http.Request, projectId ProjectPath, alertId AlertPath)
	// Update a rule
	// (PUT /v1/projects/{project_id}/alerts/{alert_id})
	UpdateAlert(w http.ResponseWriter, r *http.Request, projectId ProjectPath, alertId AlertPath)
	// Mute or unmute a rule's notifications
	// (POST /v1/projects/{project_id}/alerts/{alert_id}/mute)
	MuteAlert(w http.ResponseWriter, r *http.Request, projectId ProjectPath, alertId AlertPath)
	// Browser origins allowed to send data with the project's ingest keys
	// (GET /v1/projects/{project_id}/allowed-origins)
	GetAllowedOrigins(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Replace the allowed browser origins
	// (POST /v1/projects/{project_id}/allowed-origins)
	SetAllowedOrigins(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// List the project's ingest keys
	// (GET /v1/projects/{project_id}/keys)
	ListKeys(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Add an ingest key
	// (POST /v1/projects/{project_id}/keys)
	CreateKey(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Rotate the project's ingest key
	// (POST /v1/projects/{project_id}/keys/rotate)
	RotateKey(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Revoke one ingest key
	// (POST /v1/projects/{project_id}/keys/{key_id}/revoke)
	RevokeKey(w http.ResponseWriter, r *http.Request, projectId ProjectPath, keyId int64)
	// List the project's releases, newest first
	// (GET /v1/projects/{project_id}/releases)
	ListReleases(w http.ResponseWriter, r *http.Request, projectId ProjectPath, params ListReleasesParams)
	// Get a release and its uploaded artifacts
	// (GET /v1/projects/{project_id}/releases/{release})
	GetRelease(w http.ResponseWriter, r *http.Request, projectId ProjectPath, release ReleasePath)
	// Upload source maps for a release
	// (POST /v1/projects/{project_id}/releases/{release}/sourcemaps)
	UploadSourcemaps(w http.ResponseWriter, r *http.Request, projectId ProjectPath, release ReleasePath)
	// List the project's source map upload tokens
	// (GET /v1/projects/{project_id}/upload-tokens)
	ListUploadTokens(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Create an upload token
	// (POST /v1/projects/{project_id}/upload-tokens)
	CreateUploadToken(w http.ResponseWriter, r *http.Request, projectId ProjectPath)
	// Revoke an upload token
	// (POST /v1/projects/{project_id}/upload-tokens/{token_id}/revoke)
	RevokeUploadToken(w http.ResponseWriter, r *http.Request, projectId ProjectPath, tokenId int64)
	// Recorded sessions
	// (GET /v1/replays)
	ListReplays(w http.ResponseWriter, r *http.Request, params ListReplaysParams)
	// A recorded session with its errors and traces
	// (GET /v1/replays/{session_id})
	GetReplay(w http.ResponseWriter, r *http.Request, sessionId SessionPath, params GetReplayParams)
	// All rrweb events of the session in playback order
	// (GET /v1/replays/{session_id}/events)
	GetReplayEvents(w http.ResponseWriter, r *http.Request, sessionId SessionPath, params GetReplayEventsParams)
	// Services that sent spans in the time range
	// (GET /v1/services)
	ListServices(w http.ResponseWriter, r *http.Request, params ListServicesParams)
	// Search traces
	// (GET /v1/traces)
	ListTraces(w http.ResponseWriter, r *http.Request, params ListTracesParams)
	// Get a full trace
	// (GET /v1/traces/{trace_id})
	GetTrace(w http.ResponseWriter, r *http.Request, traceId string, params GetTraceParams)
}

